def eval_rpn(expr: str) -> int:
    stack: list[int] = []
    for tok in expr.split():
        if tok in ("+", "-", "*", "/"):
            if len(stack) < 2:
                raise ValueError("stack underflow")
            b = stack.pop()
            a = stack.pop()
            if tok == "+":
                stack.append(a + b)
            elif tok == "-":
                stack.append(a - b)
            elif tok == "*":
                stack.append(a * b)
            else:
                if b == 0:
                    raise ValueError("division by zero")
                q = abs(a) // abs(b)
                stack.append(q if (a < 0) == (b < 0) else -q)
        else:
            digits = tok[1:] if tok.startswith("-") else tok
            if digits == "" or not all("0" <= ch <= "9" for ch in digits):
                raise ValueError(f"bad token {tok}")
            stack.append(int(tok))
    if len(stack) != 1:
        raise ValueError("bad expression")
    return stack[0]
